import { GameClient, mergeCorrections, type GameClientOptions, type GamePredictionOptions, type WasmSource } from '@hops-ops/distributed/game';

import { EVENTS, type Events } from './events.ts';
import { encodeInput, type MoveInput } from './input.ts';
import { createArenaPrediction, type ArenaPrediction } from './predict.ts';
import { CORRECTIONS } from './schema.ts';

/**
 * Prediction tuning; `encodeInput`, the correction defaults and `predict` (the
 * compiled `#[predict]` step) are filled in. A `predict` given here replaces
 * the WebAssembly step.
 */
export type ArenaPredictionOptions = Omit<GamePredictionOptions<MoveInput>, 'encodeInput' | 'predict'> &
	Partial<Pick<GamePredictionOptions<MoveInput>, 'encodeInput' | 'predict'>>;

export type ArenaClientOptions = Omit<GameClientOptions<MoveInput>, 'prediction'> &
	Readonly<{
		/** Prediction tuning, or `false` for none. Default: the compiled step. */
		prediction?: ArenaPredictionOptions | false;
		/** Where to load the compiled step from (default `PREDICT_WASM_URL`). */
		wasm?: WasmSource;
	}>;

export type ArenaClient = Readonly<{
	client: GameClient<MoveInput>;
	/** The compiled step (`ready`, `setContext`); undefined when prediction is off or custom. */
	prediction: ArenaPrediction | undefined;
	/** Typed event subscription (every zone); returns the unsubscribe. */
	on<K extends keyof Events>(name: K, handler: (value: Events[K], zoneId: string) => void): () => void;
	/** Send one input: predicted when prediction is on, raw otherwise. */
	send(input: MoveInput): number | undefined;
}>;

/**
 * A `GameClient` for the `arena` surface with its input encoder, correction
 * defaults and the compiled predicted step wired in.
 */
export function createArenaClient(options: ArenaClientOptions): ArenaClient {
	const { prediction: tuning, wasm, ...rest } = options;
	const prediction =
		tuning === false || tuning?.predict !== undefined ? undefined : createArenaPrediction(wasm);
	const client = new GameClient<MoveInput>({
		...rest,
		prediction:
			tuning === false
				? undefined
				: {
						...tuning,
						predict: tuning?.predict ?? prediction!.predict,
						encodeInput: tuning?.encodeInput ?? ((input) => encodeInput(input)),
						corrections: mergeCorrections(CORRECTIONS, tuning?.corrections)
					}
	});
	return {
		client,
		prediction,
		on: (name, handler) =>
			client.on('event', (zoneId, event) => {
				const codec = EVENTS[name];
				if (event.typeId === codec.id) handler(codec.decode(event.payload), zoneId);
			}),
		send: (input) =>
			tuning === false ? client.sendRawInput(encodeInput(input)) : client.sendInput(input)
	};
}
